package helpers

import (
	"github.com/google/uuid"
	coreutils "grovehub/libs/core/utils"
)

// ValidTenantID matches School Registry's canonical UUID contract. School IDs
// are externally owned and need not be generated by Platform's UUIDv7 helper.
func ValidTenantID(raw string) bool {
	id, err := uuid.Parse(raw)
	return err == nil && id != uuid.Nil && id.String() == raw
}

// ValidID applies GrooveHub's standard UUIDv7 validation consistently.
func ValidID(raw string) bool {
	_, err := coreutils.NormalizeUUIDv7(raw)
	return err == nil
}
